INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-001','S-001','82 FR 58331 (Vol. 82, No. 236, Dec. 11, 2017)','I have determined that it is time for the United States to officially recognize Jerusalem as the capital of Israel.');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-001','S-002','White House archive, full text',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-002','The interim embassy in Jerusalem was scheduled to open on May 14, 2018','The State Department told Congress that an interim US embassy in Jerusalem, housed in an existing consular facility in the Arnona neighborhood, would open on May 14, 2018, coinciding with the 70th anniversary of Israel''s independence.','2018-05-14','policy','corroborated','policy-decision','high','The sources here pre-date the opening and describe the plan. The opening itself is widely reported but is not separately sourced in this register.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-002','p-jerusalem');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-002','us-state-dept');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-002','S-076','AP report, Feb 2018',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-002','S-079','Newsweek, Feb 23, 2018',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-003','Sheldon Adelson reportedly offered to pay for part of the Jerusalem embassy','According to four US officials who spoke to the Associated Press in February 2018, the administration was weighing an offer from Republican donor Sheldon Adelson to pay for at least part of the new embassy in Jerusalem, and State Department lawyers were examining whether private donations could legally be accepted.','2018-02-23','financial','reported','plausible-unproven','medium','Anonymous officials; a single originating report (AP). This register found no record of whether the offer was accepted or any money paid. An offer to fund a government building is not a payment to Trump.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-003','sheldon-adelson');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-003','p-jerusalem');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-003','us-state-dept');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-003','S-076','AP report reproduced by News Tribune',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-004','Trump recognized the Golan Heights as part of Israel','On March 25, 2019, President Trump signed Proclamation 9852 declaring that the United States recognizes the Golan Heights as part of the State of Israel.','2019-03-25','policy','verified','policy-decision','high','Establishes the decision only.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-004','donald-trump');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-004','p-golan');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-004','israel');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-004','S-003','84 FR 11875 (Vol. 84, No. 60, Mar. 28, 2019), operative paragraph','do hereby proclaim that, the United States recognizes that the Golan Heights are part of the State of Israel.');
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-005','Israel named a Golan community "Trump Heights" — no money involved','In June 2019 Israel''s cabinet renamed the small Golan community of Bruchim (about ten residents) "Ramat Trump" ("Trump Heights") in appreciation of the Golan recognition. Trump publicly thanked Israel for "this great honor."','2019-06-16','policy','corroborated','no-connection','high','A symbolic naming. No document reviewed shows any payment, licence fee, or property interest for Trump or his family.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-005','israel');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-005','donald-trump');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-005','p-golan');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-005','S-064','AP report',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-005','S-081','Daily Beast report',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-006','The US stopped calling West Bank settlements inconsistent with international law','On November 18, 2019, Secretary of State Mike Pompeo announced that the US would no longer follow a 1978 State Department legal opinion, and that establishing Israeli civilian settlements in the West Bank is "not per se inconsistent with international law." He said the US expressed no view on any individual settlement.','2019-11-18','policy','corroborated','policy-decision','high','The official state.gov transcript was not retrieved; the text is from a newspaper reproduction plus independent reporting.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-006','us-state-dept');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-006','p-settlements');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-006','israel');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-006','S-004','Full text of remarks',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-006','S-005','Al Jazeera report',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-007','Kushner presented a $50 billion economic plan with no named funders','In June 2019 the White House, led by Jared Kushner, released the economic portion of its "Peace to Prosperity" plan, proposing about $50 billion of investment across the Palestinian territories, Egypt, Jordan and Lebanon. It was conditional on a political settlement and did not name its funders. Kushner said he hoped wealthy Gulf states, other countries and private investors would pay for much of it.','2019-06-22','policy','corroborated','policy-decision','high','A proposal, not a funded programme. No disbursement is documented here. The political portion (January 2020) is not separately sourced in this register.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-007','jared-kushner');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-007','p-peace-prosperity');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-007','S-077','JTA, June 22, 2019',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-007','S-082','Algemeiner, June 25, 2019',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-008','Israel, the UAE and Bahrain signed the Abraham Accords at the White House','On September 15, 2020, President Trump hosted a White House ceremony at which Israel, the United Arab Emirates and Bahrain signed normalization agreements, with the US participating as a witness.','2020-09-15','policy','corroborated','policy-decision','high','The sources here do not describe Kushner''s negotiating role, so it is not asserted. Later Gulf investments in Kushner''s fund are documented separately (C-020, C-024); no document links them to the Accords.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-008','donald-trump');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-008','p-abraham');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-008','israel');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-008','uae');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-008','S-063','CBS News live coverage',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-008','S-083','Khaleej Times',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-009','The 2016 aid agreement ($38 billion, FY2019–2028) predates Trump','The US and Israel signed their third 10-year military aid memorandum in 2016, under President Obama. It covers FY2019–FY2028 and totals $38 billion ($33 billion in Foreign Military Financing plus $5 billion for missile defense), subject to annual appropriations.','2016-09','policy','verified','no-connection','high','Included as context. The baseline flow of US military aid to Israel during both Trump terms comes from an agreement signed before he took office, so it cannot be attributed to his decisions.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-009','p-mou-2016');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-009','israel');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-009','S-065','CRS RL33222 (updated Nov. 16, 2020), Summary','the United States pledged to provide—subject to congressional appropriation—$38 billion in military aid ($33 billion in Foreign Military Financing grants plus $5 billion in missile defense appropriations)');
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-010','The Trump administration fast-tracked roughly $3 billion in arms sales to Israel','On February 28, 2025, the State Department notified Congress of emergency sales to Israel, bypassing the usual congressional review. AP and CBS reported three components — bombs and warheads worth $2.04 billion, other munitions worth $675.7 million, and Caterpillar D9 bulldozers worth $295 million.','2025-02-28','policy','corroborated','policy-decision','high','The Arms Control Association describes an emergency declaration covering about $4 billion, which may be a different aggregate; the discrepancy is unresolved. These sales are paid for by Israel, including with US-funded FMF, and are not income to any Trump entity.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-010','us-state-dept');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-010','p-arms-2025');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-010','israel');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-010','S-061','CBS News, Feb 28, 2025',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-010','S-062','Arms Control Today, Apr 2025',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-011','Trump proposed a US "takeover" of Gaza and a "Riviera of the Middle East"','At a February 4, 2025 press conference with Benjamin Netanyahu, Trump proposed that the US take a long-term ownership position in Gaza, resettle its population elsewhere and lead its redevelopment, describing a possible "Riviera of the Middle East."','2025-02-04','policy','corroborated','policy-decision','high','A stated proposal. No document reviewed shows a Trump or family business interest in Gaza land or reconstruction contracts.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-011','donald-trump');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-011','p-gaza-takeover');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-011','S-055','AFP report',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-011','S-088','AP live coverage, Feb 4, 2025 ("long-term ownership position")',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-012','The 20-point Gaza plan puts reconstruction funding under a Trump-chaired Board of Peace','The White House plan of September 29, 2025 provides for a ceasefire, hostage releases, a technocratic Palestinian committee to run Gaza, and a "Board of Peace" headed and chaired by President Trump that would set the framework for, and handle the funding of, Gaza''s redevelopment.','2025-09-29','policy','corroborated','policy-decision','high','The whitehouse.gov original was not retrieved; the text comes from a full-text reprint. Chairing a body that controls funds is not, by itself, a financial benefit.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-012','donald-trump');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-012','p-gaza-plan');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-012','S-056','Reprint of plan text, point on the Board of Peace',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-012','S-084','The New Arab summary of plan',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-013','A draft Board of Peace charter reportedly sets a $1 billion fee for permanent seats','AFP and NPR reported in January 2026 that a draft Board of Peace charter exempts states contributing more than $1 billion in cash in the first year from the three-year membership term and names Trump as chairman. The White House called reports about the fee "misleading."','2026-01-19','policy','reported','plausible-unproven','medium','Based on a reported draft. This register has not seen the final charter or any record of payments. No evidence shows fees flowing to Trump personally.','The White House described reports about the fee as "misleading."');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-013','donald-trump');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-013','p-gaza-plan');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-013','S-051','AFP via Al-Monitor',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-013','S-052','NPR via Connecticut Public',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-020','Saudi Arabia''s PIF committed $2 billion to Kushner''s new fund','Saudi Arabia''s Public Investment Fund committed $2 billion to Affinity Partners, which Jared Kushner founded after leaving the White House. The New York Times reported (April 2022) that a PIF screening panel objected, citing inexperienced management and an "excessive" fee, and that the full board, chaired by Crown Prince Mohammed bin Salman, approved it anyway. Senate Finance Chairman Wyden''s 2024 letter refers to the PIF''s "$2 billion in committed funds."','2021','financial','corroborated','financial-relationship','high','A $2 billion commitment is investment capital managed by the fund, not money paid to Kushner. His personal income comes from fees and any profit share, which are not publicly broken out. The screening-panel detail rests on the NYT''s reporting of internal documents.','Affinity''s spokesperson said the firm is proud to count the PIF and other organisations with careful screening criteria among its investors.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-020','saudi-pif');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-020','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-020','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-020','S-006','Summary of NYT report',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-020','S-007','Summary of NYT report',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-020','S-009','Key findings, fee section','charging its lead investor, the Saudi Public Investment Fund, a 1.25 percent annual fee on $2 billion in committed funds.');
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-021','Senate Finance Chairman says Affinity collected up to $157M in fees with no returns','According to Senate Finance Chairman Ron Wyden''s September 25, 2024 letter, Affinity Partners had "pocketed as much as $157 million in fees from foreign clients, including $87 million from the Saudi government," and had generated no return on investment as of July 2024.','2024-09-25','oversight','verified','economic-benefit','medium','The letter is verified; its figures are the committee''s characterization from records it obtained, not audited accounts. "As much as" makes $157 million an upper bound. The $87 million is part of the $157 million and is not added to it. Fees are revenue to the firm, not Kushner''s personal income.','This register has not retrieved a response from Affinity to the specific fee figures.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-021','senate-finance');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-021','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-021','saudi-pif');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-021','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-021','S-009','Key findings section','Affinity has pocketed as much as $157 million in fees from foreign clients, including $87 million from the Saudi government.');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-021','S-011','Boston Globe summary of the letter',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-022','Wyden opened an inquiry into Gulf payments to Affinity and a possible FARA loophole','In June 2024 Senate Finance Chairman Wyden opened an inquiry into foreign payments to Affinity Partners, arguing that foreign-funded private funds could be used to avoid Foreign Agents Registration Act disclosure.','2024-06-12','oversight','corroborated','plausible-unproven','high','An inquiry is not a finding of wrongdoing. No charge or adverse legal finding against Kushner is documented here.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-022','senate-finance');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-022','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-022','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-022','S-008','Committee press release',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-022','S-085','O''Dwyer''s report on the letter',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-023','Wyden and Raskin asked DOJ for a special counsel on Kushner','On October 24, 2024, Sen. Ron Wyden and Rep. Jamie Raskin asked the Justice Department to appoint a special counsel to investigate whether Jared Kushner acted as an unregistered foreign agent.','2024-10-24','oversight','corroborated','plausible-unproven','high','A request by opposition-party lawmakers. This register found no record of a special counsel being appointed.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-023','senate-finance');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-023','house-oversight-dems');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-023','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-023','S-010','Committee press release',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-023','S-086','House Oversight Democrats release (same letter)',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-023','S-087','National Review report',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-024','Qatar''s QIA and Abu Dhabi''s Lunate added $1.5 billion to Affinity in 2024','Affinity Partners took in an additional $1.5 billion from the Qatar Investment Authority and Abu Dhabi''s Lunate, disclosed in December 2024. Kushner said the talks began in February 2024 and closed before the US election. Assets under management reached about $4.8 billion at the end of 2024, according to SEC filings cited by AGBI.','2024-12-20','financial','corroborated','financial-relationship','high','Commitments to a fund are not income to its founder. The SEC Form ADV was not retrieved directly.','Kushner framed the raise as avoiding future conflicts, saying the firm would not need to raise capital for four years.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-024','qia');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-024','lunate');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-024','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-024','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-024','S-066','Bloomberg, Dec 20, 2024',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-024','S-067','AGBI, Mar 2025',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-025','Affinity became the largest shareholder of Israeli insurer Phoenix Financial','Affinity Partners bought 4.95% of Phoenix Financial in July 2024 (about NIS 466–470 million), with an option on another 4.95% at the same valuation. In January 2025, on the last day before the option expired, Israel''s Capital Markets, Insurance and Savings Authority approved the exercise, taking Affinity to 9.9% and making it the largest shareholder, with voting rights capped at 5%.','2025-01','financial','corroborated','financial-relationship','high','The regulatory approval itself was not retrieved. Calcalist reported the option exercise produced an "instant profit" of about $72 million on paper, which is unrealized appreciation, not cash.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-025','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-025','phoenix-financial');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-025','israel');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-025','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-025','S-014','Globes, Jan 2025',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-025','S-015','Calcalist, Jan 2025',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-026','Affinity sold a quarter of its Phoenix stake for about NIS 1.05 billion','In July 2026 Affinity Partners sold about 2.5% of Phoenix Financial for roughly NIS 1.05 billion (about $343 million), cutting its stake from 9.9% to 7.4%. Its remaining stake was valued at about NIS 3.3 billion. Reports put the total gain on the original NIS 940 million investment at about NIS 3.4 billion.','2026-07','financial','corroborated','economic-benefit','medium','The NIS 3.4 billion "gain" combines realized proceeds with unrealized appreciation on the remaining shares, and accrues to the fund''s investors as well as its manager. Kushner''s personal share is not disclosed.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-026','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-026','phoenix-financial');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-026','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-026','S-012','Globes',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-026','S-013','Ynetnews',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-027','CNN found Phoenix holds stakes in Israeli military suppliers; no direct link to diplomacy found','A CNN investigation (October 2026) reported that Phoenix Financial holds investments in at least nine suppliers to the Israeli military, the largest being about $265 million in Elbit Systems. Affinity owns none of the nine directly. CNN reported no direct link between Kushner''s diplomacy and these investments.','2026-10','oversight','reported','plausible-unproven','medium','CNN''s original article was not retrieved; its findings are known from other outlets'' summaries. The exposure is indirect. Phoenix''s portfolio decisions are made by Phoenix, not Affinity.','Kushner''s attorney said he "never participated in or directed Phoenix''s decisions" about the nine companies. Kushner called the story "deeply misleading," saying Phoenix is one of Israel''s largest publicly traded financial institutions, not a defense company.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-027','phoenix-financial');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-027','elbit-systems');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-027','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-027','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-027','S-016','Ynetnews summary of CNN',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-027','S-080','Arab News summary of CNN',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-027','S-017','TheWrap, Kushner response',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-028','House Oversight''s top Democrat sought answers on Kushner''s Phoenix stake','On October 6, 2026, Rep. Robert Garcia, ranking member of the House Oversight Committee, wrote to Affinity Partners seeking information following CNN''s reporting on its Phoenix Financial stake.','2026-10-06','oversight','corroborated','plausible-unproven','high','A minority-party letter; no finding.','Kushner''s lawyer noted that Garcia himself has pension interests in Phoenix and Elbit. Garcia''s office said those pensions are managed by state systems.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-028','house-oversight-dems');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-028','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-028','jared-kushner');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-028','S-018','CNN via KION, Oct 6, 2026',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-028','S-073','Garcia office repost of NYT',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-029','Kushner negotiated the Gaza ceasefire as an unpaid envoy while Gulf states fund his firm','Kushner was sent to Sharm el-Sheikh in October 2025 to help seal the Gaza ceasefire. Several regional governments he negotiated with are investors in Affinity Partners. CNN reported that, as an unpaid envoy rather than a formal official, he was not required to file a public financial disclosure.','2025-10','diplomacy','corroborated','plausible-unproven','medium','The overlap of roles is documented. No evidence reviewed shows a specific negotiating position taken to benefit Affinity.','The White House said Kushner''s business has nothing to do with his diplomacy, which he conducts as a volunteer; press secretary Karoline Leavitt called the criticism "frankly despicable." Kushner has argued that business ties can bring Israelis and Arabs together.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-029','jared-kushner');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-029','p-gaza-plan');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-029','affinity-partners');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-029','saudi-pif');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-029','qia');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-029','S-057','NPR, Oct 23, 2025',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-029','S-058','AFP via Al-Monitor, Dec 2025',NULL);
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-029','S-080','Arab News summary of CNN (disclosure point)',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-030','PIF, Silver Lake and Affinity agreed to buy EA for $55 billion','On September 29, 2025, Electronic Arts agreed to be acquired by a consortium of Saudi Arabia''s PIF, Silver Lake and Affinity Partners at an enterprise value of about $55 billion ($210 per share in cash). PIF would roll over its existing 9.9% stake.','2025-09-29','financial','corroborated','financial-relationship','high','$55 billion is the deal''s enterprise value, not Affinity''s investment. Affinity''s equity share was not found. This register has not confirmed whether the deal has closed.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-030','electronic-arts');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-030','saudi-pif');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-030','silver-lake');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-030','affinity-partners');
