INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-030','S-020','Advanced Television, Sept 29, 2025',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-031','Raskin says Affinity has $6.16 billion under management, 99% foreign-funded','In April 2026 Rep. Jamie Raskin (House Judiciary ranking member) opened an inquiry into Kushner''s dual roles. His letter states that Affinity has about $6.16 billion in assets under management, 99% from foreign nationals including the Saudi, UAE and Qatari sovereign funds. In August 2026 he expanded the probe to a planned $120 million resort in Albania.','2026-04','oversight','reported','plausible-unproven','medium','The $6.16 billion and 99% figures are the letter''s characterization; the underlying filings were not retrieved. Kushner did not respond to the committee, per Raskin.',NULL);
