INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-032','Democrats say Kushner sought $5 billion in new foreign capital while serving as envoy','In March 2026 Sen. Wyden and Rep. Garcia wrote to the White House and Affinity Partners, citing reporting that Kushner was seeking to raise at least $5 billion in additional foreign capital while serving as an envoy.','2026-03','oversight','disputed','plausible-unproven','low','The fundraising figure rests on media reporting cited by the lawmakers, and Affinity disputes it.','Affinity''s chief legal officer said the firm has had only early-stage talks about additional fundraising and does not plan to accept new capital while Kushner volunteers for the government.');
