INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-033','Kushner called Gaza''s waterfront "very valuable" in a 2024 interview','In a February 15, 2024 interview at Harvard''s Middle East Initiative, made public in March 2024, Kushner said "Gaza''s waterfront property, it could be very valuable" and said that, from Israel''s perspective, he would do his best to move people out and then clean the area up.','2024-02-15','financial','corroborated','no-connection','high','A statement of opinion by a private citizen at the time. No document reviewed shows any Affinity or Kushner investment in Gaza property.','Kushner said on X that he stood by his comments and posted the full interview.');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-033','jared-kushner');
