INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-033','S-054','SCMP',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-034','CREW put Jared and Ivanka''s White House-era outside income at $172M–$640M','CREW''s February 2021 analysis of their financial disclosures found that Jared Kushner and Ivanka Trump reported between $172 million and $640 million in outside income while working in the White House.','2021-02-08','financial','verified','economic-benefit','medium','The range is wide because disclosures report income in broad bands. Lead Stories notes that $640 million is the upper bound, not a confirmed total. The figure is not specific to Israel or the Gulf.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-034','jared-kushner');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-034','ivanka-trump');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-034','S-059','Opening section','Jared Kushner and Ivanka Trump reported between $172 million and $640 million in outside income while working in the White House, according to an analysis of financial disclosures by CREW.');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-034','S-060','Fact check on the upper bound',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-035','An Israeli insurer invested about $30M in Kushner family properties in 2017','The New York Times reported (January 2018) that Israeli insurer Menora Mivtachim invested about $30 million in Kushner Companies'' Maryland apartment complexes in 2017, and that Kushner Companies had taken at least four loans from Bank Hapoalim.','2017-05','financial','reported','financial-relationship','medium','Known through JTA''s summary of the NYT; the original was not retrieved. The Times reported that the deal did not involve Jared Kushner personally and did not violate federal ethics law.','Menora''s real-estate head said the deal was unaffected by Kushner''s government role.');
