INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-036','The Brookfield lease that rescued 666 Fifth Avenue — the Qatar link is disputed','In 2018 Brookfield took a 99-year lease on Kushner Companies'' 666 Fifth Avenue and prepaid the rent for the full term, about $1.1–1.3 billion by various accounts, which let the Kushners clear the building''s mortgage. The Qatar Investment Authority was a major investor in Brookfield Property Partners. Sen. Wyden and Rep. Joaquin Castro investigated whether the deal influenced US policy toward Qatar.','2018-08','financial','disputed','plausible-unproven','medium','The reported lease value varies by source. A link between QIA money and the lease is contested.','Brookfield said the QIA was not involved and that it had no obligation to inform the QIA. Per Wyden''s office, Brookfield twice declined to provide requested information.');
