INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-037','The Kushner family foundation gave to a settlement yeshiva''s US fundraising arm','Tax filings analysed by Haaretz show the Charles and Seryl Kushner Foundation gave at least $38,000 to American Friends of Beit El Yeshiva between 2011 and 2013. The group''s president at the time was David Friedman, later US ambassador to Israel.','2013','financial','reported','no-connection','high','Both outlets restate Haaretz''s analysis of the tax filings; the filings were not retrieved. Charitable giving by the family foundation, legal and tax-exempt under US law. It is money flowing out of the family, not a benefit to it, and it predates the presidency.','A Kushner Companies spokesperson declined to comment.');
