INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-040','House Democrats documented at least $7.8M from foreign governments to Trump businesses','A January 2024 report by House Oversight Committee Democratic staff, based on Mazars accounting records, identified at least $7.8 million paid by at least 20 foreign governments to four Trump-owned businesses during his first term, including $615,422 from Saudi Arabia and $465,744 from Qatar.','2024-01-04','oversight','corroborated','economic-benefit','medium','A minority staff report covering only 4 of more than 500 Trump businesses, so the total is a floor. It is revenue (e.g. hotel bills), not profit. The report PDF was not retrieved; figures are from AP and the Boston Globe.','This register did not find a Trump Organization response to the specific figures.');
