INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-041','Saudi developer Dar Global licenses the Trump brand across the Gulf','Dar Global, the international arm of Saudi developer Dar Al Arkan, has licensed the Trump brand for projects in Oman (signed 2022), Jeddah (Trump Tower, December 2024), Riyadh (two projects, December 2024), Dubai (announced 2024) and a $1 billion Trump Plaza in Jeddah (September 2025). Under these deals Dar Global owns and develops the projects and the Trump Organization licenses the name.','2024-12','financial','corroborated','financial-relationship','high','Project values are developer figures, not Trump income. Licence fee terms are not public.',NULL);
