INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-042','Trump reported about $21.9M in licence fees from Dar Al Arkan in one year','Press accounts of Trump''s financial disclosures report about $21.9 million in licence fees from Dar Al Arkan in 2024, and $5.35 million in licence fees for the Oman project in 2022. Forbes reported $7.85 million from the Oman project between 2021 and early 2024.','2024','financial','reported','economic-benefit','medium','The OGE Form 278e filings were not retrieved, so figures come from secondary reporting that differs by year and project. Licence fees are revenue; profit is not disclosed.',NULL);
