INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-043','Qatar''s state developer signed for a Trump-branded golf resort near Doha','On April 30, 2025, Qatari Diar, the real-estate arm of Qatar''s sovereign wealth fund, signed an agreement with Dar Global to develop the Trump International Golf Club and Trump-branded villas at its Simaisma project north of Doha. Eric Trump attended the signing. The National reported a $5.25 million licence fee to Trump connected to the project.','2025-04-30','financial','corroborated','financial-relationship','medium','The agreement is corroborated; the $5.25 million fee comes from a single outlet. A reported ~$3 billion project cost is a single-source figure and is not used. The Trump Organization''s own release could not be retrieved (HTTP 403).',NULL);
