INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-044','The Pentagon accepted a Boeing 747-8 from Qatar','The Department of Defense accepted a Boeing 747-8 from Qatar in May 2025 for conversion to presidential use. An MOU signed in July 2025 describes it as a "bona fide gift" to the Department, at no cost to the US. ABC News reported that the terms allow Trump to use the plane after leaving office. The aircraft is commonly valued at about $400 million; the refit cost was not disclosed.','2025-05','policy','corroborated','plausible-unproven','medium','The gift was made to the US government, not to Trump personally. Post-presidency use is reported second-hand. The $400 million value is an estimate.','The Pentagon said acceptance followed all federal rules and regulations.');
