INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-045','Trump disclosed $57.35M from World Liberty token sales for 2024','Trump''s financial disclosure covering 2024, filed in June 2025, reported about $57.35 million in income from World Liberty Financial token sales.','2025-06-13','financial','corroborated','economic-benefit','high','The OGE filing was not retrieved directly. The income is not tied to Israel policy.',NULL);
