INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-046','Trump''s 2025 disclosure reported roughly $1.4 billion in crypto income','Trump''s disclosure covering 2025, filed in 2026, reported roughly $1.4 billion in cryptocurrency-linked income according to PolitiFact, including about $791 million tied to World Liberty Financial and about $635 million from a Celebration Coins (meme-coin) licensing arrangement. InvestmentNews calculated about $592 million in WLF-linked proceeds.','2026-07','financial','reported','economic-benefit','medium','Outlets disagree on totals ($592–800 million for WLF) depending on what they count. The 927-page filing was not retrieved.','Deputy press secretary Anna Kelly said neither the president nor his family would engage in conflicts of interest.');
