INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-047','Abu Dhabi''s MGX settled a $2 billion Binance investment in WLF''s USD1 stablecoin','MGX, the Abu Dhabi firm chaired by Sheikh Tahnoon bin Zayed, agreed in March 2025 to invest $2 billion in Binance. In May 2025, WLF co-founder Zach Witkoff announced that the deal would be settled in WLF''s USD1 stablecoin.','2025-05-01','financial','corroborated','plausible-unproven','medium','The $2 billion went to Binance, not WLF. How much WLF earns from the stablecoin''s reserves is not documented, so the benefit to WLF is inferred, not measured.',NULL);
