INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-048','WSJ — a Tahnoon-backed firm bought 49% of World Liberty days before the inauguration','The Wall Street Journal reported that Aryam Investment 1, an Abu Dhabi entity backed by Sheikh Tahnoon bin Zayed, agreed to buy 49% of World Liberty Financial for $500 million in an agreement signed in January 2025, four days before the inauguration. Half was reportedly paid upfront, with about $187 million going to Trump family-controlled entities and at least $31 million to entities affiliated with the Witkoff family.','2025-01-16','financial','reported','financial-relationship','medium','Single originating outlet (WSJ), known here through The Block and Ledger Insights. The WSJ article was not retrieved. Details of the payment split vary slightly between summaries.',NULL);
