INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-049','Envoy Witkoff kept a World Liberty interest despite a divestment pledge','Bloomberg reported that Steve Witkoff, the US Special Envoy to the Middle East, still held a financial interest in World Liberty Financial according to his August 2025 disclosure, despite saying in March 2025 that he was divesting and transferring the holdings to his sons.','2025-08','financial','corroborated','financial-relationship','medium','Witkoff is not a Trump family member. The disclosure did not show whether ethics officials approved his divestiture plan.',NULL);
