INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-050','Miriam Adelson gave about $100 million to a pro-Trump super PAC in 2024','According to FEC filings as reported, Miriam Adelson contributed about $100 million to Preserve America PAC, a pro-Trump super PAC, in 2024, with $95 million reported in the third quarter alone.','2024-09-30','financial','corroborated','financial-relationship','high','A political contribution to an independent-expenditure committee is not income to Trump. The FEC filing itself was not retrieved. No document reviewed links the contributions to a specific policy decision.',NULL);
