INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-051','Saudi-backed LIV Golf has played at a Trump course every season since 2022','LIV Golf, backed by Saudi Arabia''s PIF, has held at least one event at a Trump-owned course each season since 2022. LIV payments are not separately itemized in Trump''s disclosure; Trump has called the amount "peanuts," saying "They pay a rental fee."','2022','financial','reported','economic-benefit','medium','The amount paid is unknown. Club revenue figures (e.g. Doral''s $121.8 million in 2025) cover all business, not LIV.',NULL);
