INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-052','Forbes estimates of Trump''s net worth rose sharply after 2024','Forbes estimates of Trump''s net worth, as reported, rose from about $3.9–4.3 billion in 2024 to $7.3 billion in September 2025, with crypto ventures adding an estimated $2 billion. A July 2026 AP report cited a Forbes estimate of $6 billion.','2025-09','financial','reported','no-connection','low','These are third-party estimates, not disclosures, and the reported baselines conflict. Changes in net worth reflect market prices (e.g. token valuations), not realized income, and are not attributable to Israel policy.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-052','donald-trump');
INSERT INTO citation (claim_id,source_id,locator,quote) VALUES ('C-052','S-078','Nasdaq/GOBankingRates summarising Forbes',NULL);
INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-053','A Trump-licensed tower in Ramat Gan, Israel, was never built','In 2006 the Trump group and Crescent Heights bought a lot at Elite Junction in Ramat Gan, Israel, for about $44 million, intending a "Trump Plaza" tower. The Trump Organization later sued Crescent Heights over the project, and the tower was never built under the Trump name.','2006','financial','reported','no-connection','medium','Predates Trump''s political career. The lawsuit''s outcome was not found. It is listed because it is the only Trump-branded Israeli property project found in this research.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-053','trump-organization');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-053','crescent-heights');
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-053','donald-trump');
