INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-060','Inference: Gulf states are both deal counterparties and diplomatic counterparts','The record shows the same Gulf sovereign actors (Saudi Arabia''s PIF, Qatar''s QIA and Qatari Diar, and Abu Dhabi entities linked to Sheikh Tahnoon) as counterparties in Trump-family business (Affinity capital, Trump licensing, the World Liberty stake) and as parties to US Middle East diplomacy in which Trump, Kushner and Witkoff are principals. This creates documented conflict-of-interest exposure. The evidence reviewed does not show that any specific US decision on Israel was made because of these financial relationships.','2025','analysis','inference','plausible-unproven','medium','An interpretation of documented facts. Causation is not established, and much US Gulf policy had other stated rationales.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-060','saudi-pif');
