INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-061','Inference: no financial link to Trump found for the Jerusalem, Golan or settlement decisions','This research found no document linking the Jerusalem recognition, the Golan recognition or the 2019 settlements position to a payment, investment or licence benefiting Trump or his family. The largest documented money associated with pro-Israel advocacy around Trump is political contributions (for example Miriam Adelson''s ~$100 million in 2024), which are not personal income.','2019','analysis','inference','no-connection','medium','Absence of evidence within this register''s search scope is not proof of absence. Political contributions can create influence without personal enrichment; this register makes no finding on influence.',NULL);
