INSERT INTO claim (id,title,statement,event_date,track,classification,connection,confidence,limitations,responses) VALUES ('C-062','Inference: Kushner''s fund gained indirect exposure to Israeli defense-sector performance','Through its Phoenix Financial stake, Affinity Partners holds indirect exposure to Phoenix''s portfolio, which includes Israeli defense suppliers. Phoenix''s value rose substantially while Kushner was involved in Gaza diplomacy (C-026, C-029). Whether any diplomatic action affected that value is not established.','2026','analysis','inference','plausible-unproven','low','Phoenix''s share price is driven by many factors, including Israeli market performance generally. The amount of exposure attributable to defense holdings is not calculated here.',NULL);
INSERT INTO claim_entity (claim_id,entity_id) VALUES ('C-062','affinity-partners');
